function abbreviateProduct(left: number, right: number): string {
    let product = 1n;

    for (let i = left; i <= right; i++) {
        product *= BigInt(i);
    }

    let trailingZeros = 0;
    while (product % 10n === 0n) {
        product /= 10n;
        trailingZeros++;
    }

    const s = product.toString();

    if (s.length > 10) {
        return `${s.slice(0, 5)}...${s.slice(-5)}e${trailingZeros}`;
    }

    return `${s}e${trailingZeros}`;
}
