class FenwickTree {
    private tree: number[];
    private size: number;

    constructor(size: number) {
        this.size = size;
        this.tree = new Array(size + 2).fill(0);
    }

    add(index: number, delta: number): void {
        while (index <= this.size) {
            this.tree[index] += delta;
            index += index & -index;
        }
    }

    query(index: number): number {
        let sum = 0;
        while (index > 0) {
            sum += this.tree[index];
            index -= index & -index;
        }
        return sum;
    }

    kth(k: number): number {
        let index = 0;
        let bit = 1;
        while ((bit << 1) <= this.size) bit <<= 1;

        while (bit > 0) {
            const next = index + bit;
            if (next <= this.size && this.tree[next] < k) {
                index = next;
                k -= this.tree[next];
            }
            bit >>= 1;
        }

        return index + 1;
    }
}

class MKAverage {
    private m: number;
    private k: number;
    private readonly MAX_VAL = 100000;

    private countTree: FenwickTree;
    private sumTree: FenwickTree;

    private queue: number[];
    private head: number;
    private length: number;
    private totalSum: number;

    constructor(m: number, k: number) {
        this.m = m;
        this.k = k;

        this.countTree = new FenwickTree(this.MAX_VAL);
        this.sumTree = new FenwickTree(this.MAX_VAL);

        this.queue = [];
        this.head = 0;
        this.length = 0;
        this.totalSum = 0;
    }

    addElement(num: number): void {
        this.queue.push(num);
        this.length++;
        this.totalSum += num;

        this.countTree.add(num, 1);
        this.sumTree.add(num, num);

        if (this.length > this.m) {
            const removed = this.queue[this.head++];
            this.length--;
            this.totalSum -= removed;

            this.countTree.add(removed, -1);
            this.sumTree.add(removed, -removed);

            if (this.head > 10000 && this.head * 2 > this.queue.length) {
                this.queue = this.queue.slice(this.head);
                this.head = 0;
            }
        }
    }

    calculateMKAverage(): number {
        if (this.length < this.m) return -1;

        const smallestKSum = this.sumSmallest(this.k);
        const smallestMMinusKSum = this.sumSmallest(this.m - this.k);

        const middleSum = smallestMMinusKSum - smallestKSum;
        return Math.floor(middleSum / (this.m - 2 * this.k));
    }

    private sumSmallest(count: number): number {
        if (count <= 0) return 0;

        const value = this.countTree.kth(count);
        const countBefore = this.countTree.query(value - 1);
        const sumBefore = this.sumTree.query(value - 1);

        return sumBefore + (count - countBefore) * value;
    }
}

