function numSmallerByFrequency(queries: string[], words: string[]): number[] {
    const frequency = (s: string): number => {
        let smallest = '{';
        let count = 0;

        for (const ch of s) {
            if (ch < smallest) {
                smallest = ch;
                count = 1;
            } else if (ch === smallest) {
                count++;
            }
        }

        return count;
    };

    const wordFreqs = words.map(frequency).sort((a, b) => a - b);
    const n = wordFreqs.length;

    const upperBound = (target: number): number => {
        let left = 0;
        let right = n;

        while (left < right) {
            const mid = Math.floor((left + right) / 2);

            if (wordFreqs[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    };

    return queries.map(query => n - upperBound(frequency(query)));
};
```

