function canCross(stones: number[]): boolean {
    const n = stones.length;

    if (n <= 1) return true;
    if (stones[1] !== 1) return false;

    for (let i = 1; i < n; i++) {
        if (stones[i] - stones[i - 1] > i) return false;
    }

    const positionToIndex = new Map<number, number>();
    for (let i = 0; i < n; i++) {
        positionToIndex.set(stones[i], i);
    }

    const dp: Set<number>[] = Array.from({ length: n }, () => new Set<number>());
    dp[0].add(0);

    for (let i = 0; i < n; i++) {
        for (const lastJump of dp[i]) {
            for (let nextJump = lastJump - 1; nextJump <= lastJump + 1; nextJump++) {
                if (nextJump <= 0) continue;

                const nextPosition = stones[i] + nextJump;
                const nextIndex = positionToIndex.get(nextPosition);

                if (nextIndex === undefined) continue;
                if (nextIndex === n - 1) return true;

                dp[nextIndex].add(nextJump);
            }
        }
    }

    return false;
};
