function countMaxOrSubsets(nums: number[]): number {
    const n = nums.length;
    let maxOr = 0;

    for (const num of nums) {
        maxOr |= num;
    }

    let count = 0;

    const dfs = (index: number, currentOr: number): void => {
        if (currentOr === maxOr) {
            count += 1 << (n - index);
            return;
        }

        if (index === n) {
            return;
        }

        dfs(index + 1, currentOr);
        dfs(index + 1, currentOr | nums[index]);
    };

    dfs(0, 0);
    return count;
};
