function maxScore(nums: number[]): number {
    const m = nums.length;
    const totalMasks = 1 << m;

    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const gcds: number[][] = Array.from({ length: m }, () => Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            gcds[i][j] = gcd(nums[i], nums[j]);
        }
    }

    const bitCount = new Array<number>(totalMasks).fill(0);
    for (let mask = 1; mask < totalMasks; mask++) {
        bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
    }

    const dp = new Array<number>(totalMasks).fill(-1);
    dp[0] = 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        if (dp[mask] === -1) continue;

        const used = bitCount[mask];
        if (used % 2 !== 0) continue;

        const operation = used / 2 + 1;
        if (operation > m / 2) continue;

        for (let i = 0; i < m; i++) {
            if ((mask & (1 << i)) !== 0) continue;

            for (let j = i + 1; j < m; j++) {
                if ((mask & (1 << j)) !== 0) continue;

                const newMask = mask | (1 << i) | (1 << j);
                const score = dp[mask] + operation * gcds[i][j];
                if (score > dp[newMask]) {
                    dp[newMask] = score;
                }
            }
        }
    }

    return dp[totalMasks - 1];
};
