function maximumANDSum(nums: number[], numSlots: number): number {
    const pow3: number[] = new Array(numSlots + 1).fill(1);
    for (let i = 1; i <= numSlots; i++) {
        pow3[i] = pow3[i - 1] * 3;
    }

    const totalStates = pow3[numSlots];
    const count = new Int8Array(totalStates);

    for (let mask = 1; mask < totalStates; mask++) {
        count[mask] = count[Math.floor(mask / 3)] + (mask % 3);
    }

    const dp = new Int32Array(totalStates);
    dp.fill(-1);
    dp[0] = 0;

    let answer = 0;
