function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const incomplete: number[] = [];
    let alreadyFull = 0;

    for (const f of flowers) {
        if (f >= target) alreadyFull++;
        else incomplete.push(f);
    }

    incomplete.sort((a, b) => a - b);

    const m = incomplete.length;
    const prefix: number[] = new Array(m + 1).fill(0);

    for (let i = 0; i < m; i++) {
        prefix[i + 1] = prefix[i] + incomplete[i];
    }

    const lowerBound = (len: number, value: number): number => {
        let left = 0;
        let right = len;

        while (left < right) {
            const mid = Math.floor((left + right) / 2);
            if (incomplete[mid] < value) left = mid + 1;
            else right = mid;
        }

        return left;
    };

    const getBestPartial = (len: number, budget: number): number => {
        if (len === 0) return 0;

        let left = 0;
        let right = target - 1;
        let best = 0;

        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            const idx = lowerBound(len, mid);
            const cost = mid * idx - prefix[idx];

            if (cost <= budget) {
                best = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return best;
    };

    let answer = 0;
    let completeCost = 0;

    for (let madeFull = 0; madeFull <= m; madeFull++) {
        if (completeCost > newFlowers) break;

        const remainingIncomplete = m - madeFull;
        const remainingFlowers = newFlowers - completeCost;

        const partialValue = getBestPartial(remainingIncomplete, remainingFlowers);
        const beauty = (alreadyFull + madeFull) * full + partialValue * partial;

        answer = Math.max(answer, beauty);

        if (madeFull < m) {
            completeCost += target - incomplete[m - 1 - madeFull];
        }
    }

    return answer;
};
