function minMalwareSpread(graph: number[][], initial: number[]): number {
    const n = graph.length;
    initial.sort((a, b) => a - b);

    let bestNode = initial[0];
    let bestInfectedCount = Infinity;

    for (const removed of initial) {
        const infected: boolean[] = new Array(n).fill(false);
        const queue: number[] = [];
        let count = 0;

        for (const node of initial) {
            if (node !== removed) {
                infected[node] = true;
                queue.push(node);
                count++;
            }
        }

        let head = 0;
        while (head < queue.length) {
            const u = queue[head++];

            for (let v = 0; v < n; v++) {
                if (v !== removed && !infected[v] && graph[u][v] === 1) {
                    infected[v] = true;
                    queue.push(v);
                    count++;
                }
            }
        }

        if (count < bestInfectedCount) {
            bestInfectedCount = count;
            bestNode = removed;
        }
    }

    return bestNode;
}
