function minCost(maxTime: number, edges: number[][], passingFees: number[]): number {
    const n = passingFees.length;
    const INF = Number.MAX_SAFE_INTEGER;

    const dp: number[][] = Array.from({ length: maxTime + 1 }, () => Array(n).fill(INF));
    dp[0][0] = passingFees[0];

    for (let time = 1; time <= maxTime; time++) {
        for (const [u, v, travelTime] of edges) {
            if (time < travelTime) continue;

            if (dp[time - travelTime][u] !== INF) {
                dp[time][v] = Math.min(dp[time][v], dp[time - travelTime][u] + passingFees[v]);
            }

            if (dp[time - travelTime][v] !== INF) {
                dp[time][u] = Math.min(dp[time][u], dp[time - travelTime][v] + passingFees[u]);
            }
        }
    }

    let answer = INF;

    for (let time = 0; time <= maxTime; time++) {
        answer = Math.min(answer, dp[time][n - 1]);
