function minDays(grid: number[][]): number {
    const m = grid.length;
    const n = grid[0].length;

    const countIslands = (): number => {
        const visited: boolean[][] = Array.from({ length: m }, () => Array(n).fill(false));
        let islands = 0;
        const dirs = [1, 0, -1, 0, 1];

        for (let r = 0; r < m; r++) {
            for (let c = 0; c < n; c++) {
                if (grid[r][c] === 1 && !visited[r][c]) {
                    islands++;
                    if (islands > 1) return islands;

                    const stack: number[] = [r * n + c];
                    visited[r][c] = true;

                    while (stack.length > 0) {
                        const cell = stack.pop()!;
                        const x = Math.floor(cell / n);
                        const y = cell % n;

                        for (let d = 0; d < 4; d++) {
                            const nx = x + dirs[d];
                            const ny = y + dirs[d + 1];

                            if (
                                nx >= 0 &&
                                nx < m &&
                                ny >= 0 &&
                                ny < n &&
                                grid[nx][ny] === 1 &&
                                !visited[nx][ny]
                            ) {
                                visited[nx][ny] = true;
                                stack.push(nx * n + ny);
                            }
                        }
                    }
                }
            }
        }

        return islands;
    };

    if (countIslands() !== 1) return 0;

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) {
                grid[r][c] = 0;

                if (countIslands() !== 1) {
                    grid[r][c] = 1;
                    return 1;
                }

                grid[r][c] = 1;
            }
        }
    }

    return 2;
};
