function numOfWays(nums: number[]): number {
    const MOD = 1000000007;
    const MOD_BIG = BigInt(MOD);
    const n = nums.length;

    const comb: number[][] = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0));

    for (let i = 0; i <= n; i++) {
        comb[i][0] = 1;
        comb[i][i] = 1;
        for (let j = 1; j < i; j++) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
        }
    }

    const mulMod = (a: number, b: number): number => {
        return Number((BigInt(a) * BigInt(b)) % MOD_BIG);
    };

    const dfs = (arr: number[]): number => {
        const len = arr.length;
        if (len <= 2) return 1;

        const root = arr[0];
        const left: number[] = [];
        const right: number[] = [];

        for (let i = 1; i < len; i++) {
            if (arr[i] < root) {
                left.push(arr[i]);
            } else {
                right.push(arr[i]);
            }
        }

        const leftWays = dfs(left);
        const rightWays = dfs(right);

        let result = comb[len - 1][left.length];
        result = mulMod(result, leftWays);
        result = mulMod(result, rightWays);

        return result;
    };

    return (dfs(nums) - 1 + MOD) % MOD;
};
