function minDays(bloomDay: number[], m: number, k: number): number {
    const n = bloomDay.length;
    if (m * k > n) return -1;

    let left = Infinity;
    let right = -Infinity;

    for (const day of bloomDay) {
        left = Math.min(left, day);
        right = Math.max(right, day);
    }

    const canMake = (dayLimit: number): boolean => {
        let bouquets = 0;
        let adjacent = 0;

        for (const day of bloomDay) {
            if (day <= dayLimit) {
                adjacent++;

                if (adjacent === k) {
                    bouquets++;
                    adjacent = 0;

                    if (bouquets >= m) return true;
                }
            } else {
                adjacent = 0;
            }
        }

        return false;
    };

    while (left < right) {
        const mid = Math.floor(left + (right - left) / 2);

        if (canMake(mid)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return left;
};
