function friendRequests(n: number, restrictions: number[][], requests: number[][]): boolean[] {
    const parent: number[] = Array.from({ length: n }, (_, i) => i);
    const rank: number[] = Array(n).fill(0);

    const find = (x: number): number => {
        if (parent[x] !== x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    };

    const union = (a: number, b: number): void => {
        let ra = find(a);
        let rb = find(b);

        if (ra === rb) return;

        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rank[ra]++;
        }
    };

    const result: boolean[] = [];

    for (const [u, v] of requests) {
        const ru = find(u);
        const rv = find(v);

        let allowed = true;

        if (ru !== rv) {
            for (const [x, y] of restrictions) {
                const rx = find(x);
                const ry = find(y);

                if ((ru === rx && rv === ry) || (ru === ry && rv === rx)) {
                    allowed = false;
                    break;
                }
            }
        }

        if (allowed) {
            union(u, v);
            result.push(true);
        } else {
            result.push(false);
        }
    }

    return result;
}
