function removeInvalidParentheses(s: string): string[] {
    let leftRem = 0;
    let rightRem = 0;

    for (const ch of s) {
        if (ch === '(') {
            leftRem++;
        } else if (ch === ')') {
            if (leftRem > 0) {
                leftRem--;
            } else {
                rightRem++;
            }
        }
    }

    const result = new Set<string>();
    const path: string[] = [];
    const n = s.length;

    function dfs(index: number, lRem: number, rRem: number, open: number): void {
        if (lRem + rRem > n - index) return;

        if (index === n) {
            if (lRem === 0 && rRem === 0 && open === 0) {
                result.add(path.join(''));
            }
            return;
        }

        const ch = s[index];

        if (ch === '(') {
            if (lRem > 0) {
                dfs(index + 1, lRem - 1, rRem, open);
            }

            path.push(ch);
            dfs(index + 1, lRem, rRem, open + 1);
            path.pop();
        } else if (ch === ')') {
            if (rRem > 0) {
                dfs(index + 1, lRem, rRem - 1, open);
            }

            if (open > 0) {
                path.push(ch);
                dfs(index + 1, lRem, rRem, open - 1);
