        for (const num of squaresArr) {
            const square = num * num;
            count += pairsMap.get(square) || 0;
        }

        return count;
    };

    const nums1Pairs = countPairs(nums1);
    const nums2Pairs = countPairs(nums2);

    return countTriplets(nums1, nums2Pairs) + countTriplets(nums2, nums1Pairs);
};
