        for (const ch of remain) {
            need[ch.charCodeAt(0) - 97]++;
        }

        const first = remain.charCodeAt(0) - 97;
        let best = INF;

        for (const cnt of counts) {
            if (cnt[first] === 0) continue;

            const nextParts: string[] = [];

            for (let i = 0; i < 26; i++) {
                const left = need[i] - cnt[i];
                if (left > 0) {
                    nextParts.push(String.fromCharCode(97 + i).repeat(left));
