            const next = nextParts.join("");
            const sub = dfs(next);

            if (sub !== INF) {
                best = Math.min(best, sub + 1);
            }
        }

        memo.set(remain, best);
        return best;
    };

    const sortedTarget = target.split("").sort().join("");
    const answer = dfs(sortedTarget);

