function regionsBySlashes(grid: string[]): number {
    const n = grid.length;
    const size = n * n * 4;
    const parent: number[] = Array.from({ length: size }, (_, i) => i);
    const rank: number[] = Array(size).fill(0);
    let regions = size;

    function find(x: number): number {
        if (parent[x] !== x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    function union(a: number, b: number): void {
        const rootA = find(a);
        const rootB = find(b);

        if (rootA === rootB) return;

        if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }

        regions--;
    }

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const base = (i * n + j) * 4;
            const ch = grid[i][j];

            if (ch === '/') {
                union(base + 0, base + 3);
                union(base + 1, base + 2);
            } else if (ch === '\\') {
                union(base + 0, base + 1);
                union(base + 2, base + 3);
            } else {
                union(base + 0, base + 1);
                union(base + 1, base + 2);
                union(base + 2, base + 3);
            }

            if (i + 1 < n) {
                const below = ((i + 1) * n + j) * 4;
                union(base + 2, below + 0);
            }

            if (j + 1 < n) {
                const right = (i * n + j + 1) * 4;
                union(base + 1, right + 3);
            }
        }
    }

    return regions;
};
