function sortByBits(arr: number[]): number[] {
    const countBits = (num: number): number => {
        let count = 0;
        while (num > 0) {
            count += num & 1;
            num >>= 1;
        }
        return count;
    };

    return arr.sort((a, b) => {
        const bitDiff = countBits(a) - countBits(b);
        return bitDiff !== 0 ? bitDiff : a - b;
    });
