function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo = new Map<string, number[]>();
    const BASE = 32;

    const solve = (curN: number, fPos: number, sPos: number): number[] => {
        if (fPos + sPos === curN + 1) {
            return [1, 1];
        }

        if (fPos + sPos > curN + 1) {
            const newF = curN + 1 - sPos;
            const newS = curN + 1 - fPos;
            fPos = newF;
            sPos = newS;
        }

        const key = `${curN},${fPos},${sPos}`;
        const cached = memo.get(key);
        if (cached !== undefined) {
            return cached;
        }

        const nextN = Math.ceil(curN / 2);
        const half = Math.floor(curN / 2);

        const contribution = (pos: number): number => {
            if (pos < fPos) return BASE;
            if (pos > fPos && pos < sPos) return 1;
            return 0;
        };

        let states = new Set<number>();
        states.add(0);

        for (let left = 1; left <= half; left++) {
            const right = curN + 1 - left;
            const options = new Set<number>();

            if (left === fPos || right === fPos || left === sPos || right === sPos) {
                options.add(0);
            } else {
                options.add(contribution(left));
                options.add(contribution(right));
            }

            const nextStates = new Set<number>();

            for (const state of states) {
                const x = Math.floor(state / BASE);
                const y = state % BASE;

                for (const opt of options) {
                    const addX = Math.floor(opt / BASE);
                    const addY = opt % BASE;
                    nextStates.add((x + addX) * BASE + y + addY);
                }
            }

            states = nextStates;
        }

        if (curN % 2 === 1) {
            const mid = Math.floor(curN / 2) + 1;

            if (mid !== fPos && mid !== sPos) {
                const add = contribution(mid);
                const addX = Math.floor(add / BASE);
                const addY = add % BASE;

                const nextStates = new Set<number>();

                for (const state of states) {
                    const x = Math.floor(state / BASE);
                    const y = state % BASE;
                    nextStates.add((x + addX) * BASE + y + addY);
                }

                states = nextStates;
            }
        }

        let earliest = Number.POSITIVE_INFINITY;
        let latest = 0;

        for (const state of states) {
            const beforeFirst = Math.floor(state / BASE);
            const betweenPlayers = state % BASE;

            const nextF = beforeFirst + 1;
            const nextS = beforeFirst + betweenPlayers + 2;

            const [subEarliest, subLatest] = solve(nextN, nextF, nextS);

            earliest = Math.min(earliest, subEarliest + 1);
            latest = Math.max(latest, subLatest + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    };

    return solve(n, firstPlayer, secondPlayer);
};
