function getCoprimes(nums: number[], edges: number[][]): number[] {
    const n = nums.length;

    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const coprimeVals: number[][] = Array.from({ length: 51 }, () => []);
    for (let i = 1; i <= 50; i++) {
        for (let j = 1; j <= 50; j++) {
            if (gcd(i, j) === 1) coprimeVals[i].push(j);
        }
    }

    const m = edges.length;
    const head = new Int32Array(n);
    head.fill(-1);

    const to = new Int32Array(2 * m);
    const next = new Int32Array(2 * m);
    let edgeIndex = 0;

    for (let i = 0; i < m; i++) {
        const u = edges[i][0];
        const v = edges[i][1];

        to[edgeIndex] = v;
        next[edgeIndex] = head[u];
        head[u] = edgeIndex++;

        to[edgeIndex] = u;
        next[edgeIndex] = head[v];
        head[v] = edgeIndex++;
    }

    const ans = new Array<number>(n).fill(-1);
    const depth = new Int32Array(n);
    const valueStacks: number[][] = Array.from({ length: 51 }, () => []);

    const stackSize = 2 * n + 5;
    const stackNode = new Int32Array(stackSize);
    const stackParent = new Int32Array(stackSize);
    const stackDepth = new Int32Array(stackSize);
    const stackState = new Int8Array(stackSize);

    let sp = 0;
    stackNode[sp] = 0;
    stackParent[sp] = -1;
    stackDepth[sp] = 0;
    stackState[sp] = 0;
    sp++;

    while (sp > 0) {
        sp--;

        const node = stackNode[sp];
        const parent = stackParent[sp];
        const d = stackDepth[sp];
        const state = stackState[sp];

        const val = nums[node];

        if (state === 1) {
            valueStacks[val].pop();
            continue;
        }

        depth[node] = d;

        let bestDepth = -1;
        let bestNode = -1;
        const candidates = coprimeVals[val];

        for (let i = 0; i < candidates.length; i++) {
            const stack = valueStacks[candidates[i]];
            if (stack.length > 0) {
                const ancestor = stack[stack.length - 1];
                if (depth[ancestor] > bestDepth) {
                    bestDepth = depth[ancestor];
                    bestNode = ancestor;
                }
            }
        }

        ans[node] = bestNode;

        valueStacks[val].push(node);

        stackNode[sp] = node;
        stackParent[sp] = parent;
        stackDepth[sp] = d;
        stackState[sp] = 1;
        sp++;

        for (let e = head[node]; e !== -1; e = next[e]) {
            const nei = to[e];
            if (nei === parent) continue;

            stackNode[sp] = nei;
            stackParent[sp] = node;
            stackDepth[sp] = d + 1;
            stackState[sp] = 0;
            sp++;
        }
    }

    return ans;
};
